import { useState, useEffect } from 'react';
import axios from 'axios';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { Activity, ShieldAlert, Play, TestTube, AlertTriangle, CheckCircle, Hexagon, Fingerprint, BookOpen, X } from 'lucide-react';

const MicroscopicBackground = () => {
  const [particles, setParticles] = useState([]);

  useEffect(() => {
    const colors = [
      'rgba(244, 63, 93, 0.51)',
      'rgba(6, 181, 212, 0.5)',
      'rgba(14, 164, 233, 0.5)',
      'rgba(14, 233, 14, 0.5)'
    ];

    const newParticles = Array.from({ length: 30 }).map((_, i) => {
      const moveX = (Math.random() * 100 - 50) + 'px';
      const moveY = (Math.random() * 100 - 50) + 'px';
      
      return {
        id: i,
        top: `${Math.random() * 100}%`,
        left: `${Math.random() * 100}%`,
        size: `${Math.random() * 250 + 50}px`,
        delay: `${Math.random() * 5}s`,
        duration: `${Math.random() * 8 + 6}s`, 
        color: colors[i % colors.length],
        moveX,
        moveY
      };
    });
    setParticles(newParticles);
  }, []);

  return (
    <div className="fixed inset-0 z-0 overflow-hidden pointer-events-none bg-[#010308]">
      <style>
        {`
          @keyframes floatMicrobe {
            0% { transform: translate(0, 0) scale(0.8); opacity: 0; }
            50% { opacity: 1; }
            100% { transform: translate(var(--moveX), var(--moveY)) scale(1.2); opacity: 0; }
          }
        `}
      </style>

      {particles.map(p => (
        <div
          key={p.id}
          className="absolute rounded-full blur-[50px]"
          style={{
            top: p.top, left: p.left, width: p.size, height: p.size,
            backgroundColor: p.color,
            animation: `floatMicrobe ${p.duration} infinite ease-in-out ${p.delay}`,
            '--moveX': p.moveX,
            '--moveY': p.moveY
          }}
        />
      ))}
      <div className="absolute inset-0 bg-[linear-gradient(rgba(8,145,178,0.05)_1px,transparent_1px),linear-gradient(90deg,rgba(8,145,178,0.05)_1px,transparent_1px)] bg-[size:40px_40px]" />
      <div className="absolute inset-0 bg-gradient-to-b from-transparent via-[#010308]/60 to-[#010308]" />
    </div>
  );
};

const bioClinicalData = {
  "Escherichia coli": {
    type: "Gram-negativa | Bastonete",
    image: "data:image/jpeg;base64,",
    desc: "Habitante da microbiota intestinal, principal causadora de Infecções do Trato Urinário (ITU) e sepse grave em ambiente hospitalar.",
    virulence: "Adesinas específicas, toxina Shiga, cápsula polissacarídica antifagocítica.",
    resistance: "Produção de Beta-lactamases de Espectro Estendido (ESBL)."
  },
  "Staphylococcus aureus (MRSA)": {
    type: "Gram-positiva | Cocos em Cachos",
    image: "data:image/jpeg;base64,",
    desc: "Patógeno hiper-resistente temido em UTIs. Causa infecções agressivas de pele, tecido ósseo, pulmões e corrente sanguínea.",
    virulence: "Enzima coagulase, Toxina da Síndrome do Choque Tóxico (TSST-1), leucocidina.",
    resistance: "Alteração estrutural da PBP2a (gene mecA), conferindo resistência cruzada."
  },
  "Pseudomonas aeruginosa": {
    type: "Gram-negativa | Bacilo",
    image: "data:image/jpeg;base64,",
    desc: "Bactéria oportunista de altíssima letalidade em pacientes imunocomprometidos e vítimas de queimaduras. Extremamente adaptável ao meio.",
    virulence: "Exotoxina A, formação de biofilme espesso, sistema de secreção tipo III.",
    resistance: "Hiper-expressão de bombas de efluxo e beta-lactamases cromossômicas (AmpC)."
  }
};

function App() {
  const [bacteriaList, setBacteriaList] = useState([]);
  const [selectedBacteria, setSelectedBacteria] = useState('');
  const [initialLoad, setInitialLoad] = useState(1000000);
  const [treatmentDays, setTreatmentDays] = useState(14);
  
  const [simulationData, setSimulationData] = useState(null);
  const [activeTab, setActiveTab] = useState('');
  const [loading, setLoading] = useState(false);
  const [showMathModal, setShowMathModal] = useState(false); // Estado do Modal

  useEffect(() => {
    const fetchBacteria = async () => {
      try {
        const response = await axios.get('http://localhost:8080/api/pathogens/unique');
        setBacteriaList(response.data);
        if (response.data.length > 0) setSelectedBacteria(response.data[0]);
      } catch (error) {
        console.error("Erro ao buscar lista de bactérias:", error);
      }
    };
    fetchBacteria();
  }, []);

  const runComparison = async () => {
    setLoading(true);
    try {
      const response = await axios.post('http://localhost:8080/api/simulations/compare', {
        bacteriaName: selectedBacteria,
        initialBacterialLoad: initialLoad,
        treatmentDays: treatmentDays
      });
      if (response.data && response.data.results.length > 0) {
        setSimulationData(response.data);
        setActiveTab(response.data.results[0].antibioticName);
      }
    } catch (error) {
      console.error("Erro na simulação:", error);
      alert("Falha na varredura numérico-computacional.");
    } finally {
      setLoading(false);
    }
  };

  const currentTabResult = simulationData?.results.find(r => r.antibioticName === activeTab);
  const currentBioInfo = bioClinicalData[selectedBacteria];

  return (
    <>
      <MicroscopicBackground />
      
      {/* MODAL DE FUNDAMENTAÇÃO MATEMÁTICA */}
      {showMathModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <div className="bg-[#020617]/90 backdrop-blur-xl border border-cyan-500/30 rounded-2xl p-8 max-w-3xl w-full shadow-[0_0_50px_rgba(8,145,178,0.3)] relative overflow-hidden">
            <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-cyan-400 to-blue-600"></div>
            
            <button 
              onClick={() => setShowMathModal(false)}
              className="absolute top-6 right-6 text-cyan-500 hover:text-cyan-300 transition-colors"
            >
              <X size={24} />
            </button>

            <h2 className="text-2xl font-bold text-cyan-50 flex items-center gap-3 border-b border-white/10 pb-4 mb-6">
              <BookOpen className="text-cyan-400" />
              Fundamentação Matemática (EDOs)
            </h2>

            <div className="space-y-6">
              <div className="bg-black/50 border border-cyan-900/50 p-6 rounded-xl font-mono text-lg text-center tracking-wide shadow-[inset_0_0_20px_rgba(0,0,0,0.5)]">
                <p className="text-cyan-300 mb-4">
                  <span className="text-cyan-600 font-bold">dS/dt</span> = r · S <span className="text-cyan-600/50">(1 - (S+R)/K)</span> - a · S - m · S
                </p>
                <p className="text-rose-300">
                  <span className="text-rose-600 font-bold">dR/dt</span> = r · R <span className="text-rose-600/50">(1 - (S+R)/K)</span> + m · S
                </p>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-sm text-cyan-100/80">
                <div className="bg-white/5 p-4 rounded-lg border border-white/5">
                  <p className="font-bold text-cyan-400 mb-1 flex items-center gap-2"><span className="w-2 h-2 rounded-full bg-cyan-400"></span>S e R (Variáveis de Estado)</p>
                  <p className="text-xs">Representam as populações instantâneas de bactérias Suscetíveis e Resistentes.</p>
                </div>
                <div className="bg-white/5 p-4 rounded-lg border border-white/5">
                  <p className="font-bold text-cyan-400 mb-1 flex items-center gap-2"><span className="w-2 h-2 rounded-full bg-cyan-400"></span>K (Capacidade de Carga)</p>
                  <p className="text-xs">Limite físico/nutricional do ambiente. Modela o freio do crescimento (Equação de Verhulst).</p>
                </div>
                <div className="bg-white/5 p-4 rounded-lg border border-white/5">
                  <p className="font-bold text-rose-400 mb-1 flex items-center gap-2"><span className="w-2 h-2 rounded-full bg-rose-400"></span>m (Taxa de Mutação)</p>
                  <p className="text-xs">Probabilidade da bactéria alterar seu DNA, subtraída de S e adicionada em R.</p>
                </div>
                <div className="bg-white/5 p-4 rounded-lg border border-white/5">
                  <p className="font-bold text-blue-400 mb-1 flex items-center gap-2"><span className="w-2 h-2 rounded-full bg-blue-400"></span>a (Eficácia do Fármaco)</p>
                  <p className="text-xs">Taxa de mortalidade imposta apenas sobre a cepa suscetível (S) pelo antibiótico.</p>
                </div>
              </div>

              <p className="text-xs text-cyan-600/80 font-mono text-center pt-2 border-t border-white/5">
                * Resolução numérica via Integração Computacional de Runge-Kutta (SciPy Python Engine).
              </p>
            </div>
          </div>
        </div>
      )}

      <div className="relative z-10 min-h-screen text-cyan-50 p-8 font-sans selection:bg-cyan-500/30">
        
        <header className="mb-8 p-6 rounded-2xl bg-black/30 backdrop-blur-md border border-cyan-500/20 shadow-[0_8px_32px_rgba(0,0,0,0.5)] flex justify-between items-center">
          <div>
            <h1 className="text-3xl font-bold flex items-center gap-3 text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 to-blue-500 tracking-wide uppercase drop-shadow-lg">
              <Hexagon className="text-cyan-400" size={36} strokeWidth={1.5} />
              Antimicrobial Resistance Modeling
            </h1>
            <p className="text-cyan-400/70 mt-2 text-sm tracking-widest uppercase">Dinâmica Populacional // Resolução de EDO Logísticas</p>
          </div>
          <div className="text-right text-xs text-cyan-600 font-mono hidden md:block">
            <p>SYS.STATUS: <span className="text-emerald-400 drop-shadow-[0_0_5px_#34d399]">ONLINE</span></p>
            <p>DB.CONNECTION: <span className="text-emerald-400 drop-shadow-[0_0_5px_#34d399]">SECURE</span></p>
          </div>
        </header>

        <div className="grid grid-cols-1 xl:grid-cols-4 gap-8">
          
          <aside className="xl:col-span-1 bg-black/40 backdrop-blur-xl p-6 rounded-2xl border border-white/5 shadow-[0_8px_32px_rgba(0,0,0,0.5)] flex flex-col gap-6 h-fit relative overflow-hidden">
            <div className="absolute -right-4 -top-4 text-cyan-500/10">
              <Fingerprint size={120} />
            </div>
            
            <h2 className="text-lg font-semibold flex items-center gap-2 border-b border-white/10 pb-3 text-cyan-300 uppercase tracking-wider relative z-10">
              <TestTube size={20} />
              Input de Variáveis
            </h2>

            <div className="relative z-10">
              <label className="block text-xs font-medium text-cyan-500 uppercase tracking-widest mb-2">Cepa Bacteriológica</label>
              <select 
                value={selectedBacteria} 
                onChange={(e) => setSelectedBacteria(e.target.value)}
                className="w-full bg-black/50 border border-cyan-500/30 text-cyan-100 rounded-xl p-3 outline-none focus:border-cyan-400 focus:ring-1 focus:ring-cyan-400 transition-all text-sm backdrop-blur-md appearance-none"
              >
                {bacteriaList.map((b, idx) => (
                  <option key={idx} value={b} className="bg-slate-900">{b}</option>
                ))}
              </select>
            </div>

            <div className="relative z-10">
              <label className="block text-xs font-medium text-cyan-500 uppercase tracking-widest mb-2 flex justify-between">
                <span>População Inicial (S₀ + R₀)</span>
                <span className="text-cyan-300">{initialLoad.toLocaleString()} UFC</span>
              </label>
              <input 
                type="range" min="100000" max="10000000" step="100000"
                value={initialLoad} onChange={(e) => setInitialLoad(Number(e.target.value))}
                className="w-full accent-cyan-400 h-1.5 bg-cyan-950/50 rounded-lg appearance-none cursor-pointer outline-none"
              />
            </div>

            <div className="relative z-10">
              <label className="block text-xs font-medium text-cyan-500 uppercase tracking-widest mb-2 flex justify-between">
                <span>Passos de Integração (t)</span>
                <span className="text-cyan-300">{treatmentDays} dias</span>
              </label>
              <input 
                type="range" min="7" max="30" step="1"
                value={treatmentDays} onChange={(e) => setTreatmentDays(Number(e.target.value))}
                className="w-full accent-cyan-400 h-1.5 bg-cyan-950/50 rounded-lg appearance-none cursor-pointer outline-none"
              />
            </div>

            <div className="relative z-10 flex gap-2 mt-4">
              <button 
                onClick={runComparison}
                disabled={loading || !selectedBacteria}
                className="flex-1 bg-gradient-to-r from-cyan-600/20 to-blue-600/20 border border-cyan-400/50 hover:from-cyan-500/40 hover:to-blue-500/40 text-cyan-100 font-bold py-3 px-4 rounded-xl flex justify-center items-center gap-2 transition-all uppercase tracking-widest text-[10px] disabled:opacity-50 disabled:cursor-not-allowed shadow-[0_0_15px_rgba(34,211,238,0.2)] hover:shadow-[0_0_25px_rgba(34,211,238,0.5)]"
              >
                {loading ? "Calculando..." : <><Play size={14} /> Processar Dados</>}
              </button>
              
              <button 
                onClick={() => setShowMathModal(true)}
                className="bg-black/50 border border-cyan-500/30 hover:border-cyan-400 hover:bg-cyan-900/30 text-cyan-300 p-3 rounded-xl transition-all shadow-[0_0_10px_rgba(8,145,178,0.2)] flex items-center justify-center"
                title="Fundamentação Matemática"
              >
                <BookOpen size={18} />
              </button>
            </div>

            {currentBioInfo && (
              <div className="mt-4 pt-6 border-t border-white/10 relative z-10">
                <h3 className="text-[10px] font-bold text-cyan-500 uppercase tracking-widest mb-3">Dossiê Clínico do Isolado</h3>
                <div className="bg-black/50 border border-cyan-500/20 rounded-xl p-4 flex flex-col gap-4 shadow-[inset_0_0_15px_rgba(8,145,178,0.1)]">
                  
                  <div className="flex gap-4 border-b border-cyan-900/50 pb-4">
                    <div className="w-16 h-16 rounded-lg overflow-hidden border border-cyan-500/30 flex-shrink-0 shadow-[0_0_10px_rgba(34,211,238,0.2)]">
                      <img 
                        src={currentBioInfo.image} 
                        alt={selectedBacteria} 
                        className="w-full h-full object-cover grayscale opacity-80 hover:grayscale-0 hover:opacity-100 transition-all duration-500" 
                      />
                    </div>
                    <div className="flex flex-col justify-center">
                      <p className="text-sm font-bold text-cyan-50 drop-shadow-md leading-tight">{selectedBacteria}</p>
                      <p className="text-[10px] text-cyan-400 font-mono tracking-wide mt-1">{currentBioInfo.type}</p>
                    </div>
                  </div>
                  
                  <div className="space-y-3">
                    <div>
                      <p className="text-[9px] text-cyan-600 font-bold uppercase tracking-widest mb-1">Patogênese</p>
                      <p className="text-xs text-cyan-100/80 leading-relaxed text-justify">{currentBioInfo.desc}</p>
                    </div>
                    <div>
                      <p className="text-[9px] text-cyan-600 font-bold uppercase tracking-widest mb-1">Fatores de Virulência</p>
                      <p className="text-[11px] text-cyan-300/90 font-mono leading-relaxed">{currentBioInfo.virulence}</p>
                    </div>
                    <div>
                      <p className="text-[9px] text-cyan-600 font-bold uppercase tracking-widest mb-1">Mecanismo AMR Comum</p>
                      <p className="text-[11px] text-rose-300/90 font-mono leading-relaxed">{currentBioInfo.resistance}</p>
                    </div>
                  </div>

                </div>
              </div>
            )}
          </aside>

          <main className="xl:col-span-3 flex flex-col gap-6">
            {simulationData ? (
              <>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  {simulationData.results.map((res, idx) => {
                    const isHighRisk = res.baseMutationRate > 0.0001 || res.antibioticEfficacy < 0.5;
                    return (
                      <div 
                        key={idx} 
                        onClick={() => setActiveTab(res.antibioticName)}
                        className={`p-5 rounded-2xl border backdrop-blur-xl cursor-pointer transition-all duration-300 flex flex-col gap-3 relative overflow-hidden ${
                          activeTab === res.antibioticName 
                            ? 'bg-cyan-950/40 border-cyan-400/80 shadow-[0_0_20px_rgba(34,211,238,0.2)]' 
                            : 'bg-black/40 border-white/10 hover:bg-white/5 hover:border-cyan-500/30'
                        }`}
                      >
                        {activeTab === res.antibioticName && (
                          <div className="absolute top-0 left-0 w-1.5 h-full bg-cyan-400 shadow-[0_0_15px_#22d3ee]"></div>
                        )}
                        <div className="flex justify-between items-center z-10">
                          <span className="font-bold text-lg text-white tracking-wide">{res.antibioticName}</span>
                          {isHighRisk ? (
                            <AlertTriangle className="text-rose-400 drop-shadow-[0_0_8px_rgba(244,63,94,0.8)]" size={20} />
                          ) : (
                            <CheckCircle className="text-emerald-400 drop-shadow-[0_0_8px_rgba(52,211,153,0.8)]" size={20} />
                          )}
                        </div>
                        <div className="text-xs text-cyan-200/60 space-y-1.5 font-mono z-10 mt-2">
                          <p>MORTALIDADE FÁRMACO (a): <span className="text-cyan-300 font-semibold">{res.antibioticEfficacy}</span></p>
                          <p>TRANSIÇÃO GENÉTICA (m): <span className="text-cyan-300 font-semibold">{(res.baseMutationRate * 100).toFixed(4)}%</span> <span className="opacity-50">({res.baseMutationRate.toExponential(1)})</span></p>
                        </div>
                        <div className={`mt-auto text-[10px] font-bold py-1.5 px-2 rounded-lg tracking-widest uppercase text-center border backdrop-blur-sm z-10 ${
                          isHighRisk ? 'bg-rose-900/20 text-rose-300 border-rose-500/30' : 'bg-emerald-900/20 text-emerald-300 border-emerald-500/30'
                        }`}>
                          {isHighRisk ? "Vantagem Competitiva" : "Erradicação Estável"}
                        </div>
                      </div>
                    );
                  })}
                </div>

                <div className="bg-black/40 backdrop-blur-xl p-6 rounded-2xl border border-white/5 shadow-[0_8px_32px_rgba(0,0,0,0.5)]">
                  <div className="flex items-center justify-between mb-6 border-b border-white/10 pb-4">
                    <h2 className="text-lg font-semibold flex items-center gap-2 text-white tracking-wide uppercase drop-shadow-md">
                      <ShieldAlert className="text-cyan-400" size={20} />
                      Convergência Numérica // {activeTab}
                    </h2>
                    <div className="flex items-center gap-2 bg-black/50 px-3 py-1.5 rounded-full border border-white/10">
                      <span className="w-2 h-2 rounded-full bg-rose-500 animate-pulse shadow-[0_0_8px_#f43f5e]"></span>
                      <span className="text-[10px] text-cyan-400 font-mono tracking-widest">LIVE TRACKING</span>
                    </div>
                  </div>
                  
                  <div className="w-full h-[450px]">
                    <ResponsiveContainer width="100%" height="100%">
                      <LineChart data={currentTabResult?.projectionData} margin={{ top: 10, right: 30, left: 0, bottom: 5 }}>
                        <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.05)" vertical={false} />
                        <XAxis 
                          dataKey="day" 
                          stroke="rgba(255,255,255,0.3)" 
                          type="number"
                          domain={[0, 'dataMax']}
                          ticks={Array.from({length: treatmentDays + 1}, (_, i) => i)}
                          tick={{ fill: 'rgba(255,255,255,0.6)', fontSize: 12, fontFamily: 'monospace' }}
                          tickLine={false}
                          axisLine={{ stroke: 'rgba(255,255,255,0.1)' }}
                        />
                        <YAxis 
                          stroke="rgba(255,255,255,0.3)" 
                          tick={{ fill: 'rgba(255,255,255,0.6)', fontSize: 12, fontFamily: 'monospace' }}
                          tickLine={false}
                          axisLine={{ stroke: 'rgba(255,255,255,0.1)' }}
                        />
                        <Tooltip 
                          contentStyle={{ backgroundColor: 'rgba(0, 0, 0, 0.7)', border: '1px solid rgba(34, 211, 238, 0.3)', color: '#fff', borderRadius: '12px', backdropFilter: 'blur(8px)', boxShadow: '0 4px 20px rgba(0,0,0,0.5)' }}
                          itemStyle={{ fontFamily: 'monospace' }}
                        />
                        <Legend verticalAlign="top" height={36} iconType="circle" wrapperStyle={{ fontSize: '12px', color: 'rgba(255,255,255,0.8)' }} />
                        <Line type="monotone" dataKey="susceptible" name="Suscetíveis" stroke="#22d3ee" strokeWidth={3} dot={false} activeDot={{ r: 6, fill: '#22d3ee', stroke: '#000', strokeWidth: 2 }} />
                        <Line type="monotone" dataKey="resistant" name="Resistentes" stroke="#fb7185" strokeWidth={3} dot={false} activeDot={{ r: 6, fill: '#fb7185', stroke: '#000', strokeWidth: 2 }} />
                      </LineChart>
                    </ResponsiveContainer>
                  </div>
                </div>
              </>
            ) : (
              <div className="flex-grow min-h-[500px] flex flex-col items-center justify-center text-cyan-600/50 border border-dashed border-white/10 rounded-2xl bg-black/20 backdrop-blur-sm p-8 text-center relative overflow-hidden shadow-[inset_0_0_50px_rgba(0,0,0,0.5)]">
                <Activity size={64} className="text-cyan-500/40 mb-6 animate-pulse" />
                <p className="text-xl font-medium text-cyan-300 tracking-widest uppercase drop-shadow-md">Motor Matemático Pronto</p>
                <p className="text-sm text-cyan-500/70 max-w-md mt-4 font-mono leading-relaxed">
                  &gt; SELECIONE OS PARÂMETROS BIOLÓGICOS À ESQUERDA PARA INICIAR A RESOLUÇÃO NUMÉRICA DA DINÂMICA POPULACIONAL (MÉTODO DE INTEGRAÇÃO SCIPY).
                </p>
              </div>
            )}
          </main>
        </div>
      </div>
    </>
  );
}

export default App;